import { dateKeysInRange, toDateKey, type DateKey } from '@/lib/date';
import { KCAL_PER_GRAM, sumNutrients } from '@/features/nutrition';
import type { FoodEntry, FoodInsight, InsightKind } from '@/types/domain';

/**
 * Food Memory, first version.
 *
 * Every insight here is computed from entries the user actually saved, and
 * every one carries the ids of the entries it used plus a plain-language note
 * on how it was counted. Nothing is generated by a language model, and nothing
 * is produced when there is not enough data to support it.
 *
 * This is the deliberate boundary of the first version: counting and averaging
 * over real records. Predictive personalization is a later phase.
 */

/** Below these thresholds we say "not enough data" rather than guess. */
export const MIN_ENTRIES_FOR_INSIGHTS = 3;
export const MIN_DAYS_FOR_INSIGHTS = 2;
/** A food must appear on this many separate days to count as a repeat. */
export const MIN_DAYS_FOR_REPEAT = 2;

/**
 * Whether there is enough logged for insights to say anything.
 *
 * Exported so the screens that link to Insights can ask before offering the
 * link. Home and Progress both advertised "Patterns counted from your saved
 * meals" from the first launch, and the link led to "Not enough logged yet" -
 * which reads as a broken feature rather than as one that has not started.
 *
 * Takes the two counts rather than the entries: both callers already hold a
 * day-by-day summary and neither should have to re-read the journal to
 * decide whether to draw a row.
 */
export function hasEnoughForInsights(entryCount: number, daysLogged: number): boolean {
  return entryCount >= MIN_ENTRIES_FOR_INSIGHTS && daysLogged >= MIN_DAYS_FOR_INSIGHTS;
}

export interface InsightWindow {
  periodStart: DateKey;
  periodEnd: DateKey;
}

export interface DataSufficiency {
  sufficient: boolean;
  entryCount: number;
  daysLogged: number;
  /** What the user needs to do for insights to appear. */
  requirement: string;
}

export interface InsightResult {
  insights: FoodInsight[];
  sufficiency: DataSufficiency;
}

/**
 * Generate insights for a window.
 *
 * @param entries Entries whose `consumedAt` falls inside the window. Entries
 *                outside it are ignored rather than silently included.
 * @param userId  Owner, copied onto each insight.
 */
export function generateInsights(
  entries: readonly FoodEntry[],
  userId: string,
  window: InsightWindow,
): InsightResult {
  const windowKeys = new Set(dateKeysInRange(window.periodStart, window.periodEnd));
  const inWindow = entries.filter((entry) =>
    windowKeys.has(toDateKey(new Date(entry.consumedAt))),
  );

  const daysLogged = new Set(
    inWindow.map((entry) => toDateKey(new Date(entry.consumedAt))),
  ).size;

  const sufficiency: DataSufficiency = {
    sufficient:
      inWindow.length >= MIN_ENTRIES_FOR_INSIGHTS && daysLogged >= MIN_DAYS_FOR_INSIGHTS,
    entryCount: inWindow.length,
    daysLogged,
    requirement: `Insights need at least ${MIN_ENTRIES_FOR_INSIGHTS} meals logged across ${MIN_DAYS_FOR_INSIGHTS} different days.`,
  };

  if (!sufficiency.sufficient) {
    return { insights: [], sufficiency };
  }

  const insights: FoodInsight[] = [];
  const push = (insight: FoodInsight | null) => {
    if (insight) insights.push(insight);
  };

  push(buildWeeklySummary(inWindow, userId, window, daysLogged));
  push(buildRepeatMeal(inWindow, userId, window));
  push(buildMacroBalance(inWindow, userId, window, daysLogged));
  push(buildVariety(inWindow, userId, window));
  push(buildLoggingStreak(inWindow, userId, window));

  return { insights, sufficiency };
}

function makeInsight(
  kind: InsightKind,
  userId: string,
  window: InsightWindow,
  headline: string,
  detail: string,
  entryIds: string[],
  method: string,
): FoodInsight {
  return {
    // Deterministic id: regenerating the same window replaces rather than
    // duplicates, which matters once these are cached server-side.
    id: `${kind}:${window.periodStart}:${window.periodEnd}`,
    userId,
    kind,
    periodStart: window.periodStart,
    periodEnd: window.periodEnd,
    headline,
    detail,
    evidence: { entryCount: entryIds.length, entryIds, method },
    createdAt: new Date().toISOString(),
  };
}

function buildWeeklySummary(
  entries: readonly FoodEntry[],
  userId: string,
  window: InsightWindow,
  daysLogged: number,
): FoodInsight {
  const totals = sumNutrients(entries.flatMap((e) => e.items.map((i) => i.nutrients)));
  const perLoggedDay = Math.round(totals.nutrients.caloriesKcal / daysLogged);
  const windowDays = dateKeysInRange(window.periodStart, window.periodEnd).length;

  return makeInsight(
    'weekly_summary',
    userId,
    window,
    `About ${perLoggedDay} kcal on the days you logged`,
    `You logged ${entries.length} meals across ${daysLogged} of ${windowDays} days. That averages ${perLoggedDay} kcal per logged day. Days with nothing logged are left out rather than counted as zero.`,
    entries.map((e) => e.id),
    `Summed the calories of every item in ${entries.length} saved meals, then divided by the ${daysLogged} days that had at least one meal.`,
  );
}

function buildRepeatMeal(
  entries: readonly FoodEntry[],
  userId: string,
  window: InsightWindow,
): FoodInsight | null {
  // Count the DAYS a food appears on, not the number of items: three portions
  // in one meal is not a habit.
  const daysByFood = new Map<string, { label: string; days: Set<DateKey>; entryIds: Set<string> }>();

  for (const entry of entries) {
    const dayKey = toDateKey(new Date(entry.consumedAt));
    for (const item of entry.items) {
      const label = item.name.trim();
      if (label.length === 0) continue;
      const key = label.toLowerCase();
      const existing = daysByFood.get(key);
      if (existing) {
        existing.days.add(dayKey);
        existing.entryIds.add(entry.id);
      } else {
        daysByFood.set(key, {
          label,
          days: new Set([dayKey]),
          entryIds: new Set([entry.id]),
        });
      }
    }
  }

  let best: { label: string; days: number; entryIds: string[] } | null = null;
  for (const value of daysByFood.values()) {
    if (value.days.size < MIN_DAYS_FOR_REPEAT) continue;
    if (!best || value.days.size > best.days) {
      best = { label: value.label, days: value.days.size, entryIds: [...value.entryIds] };
    }
  }

  if (!best) return null;

  return makeInsight(
    'repeat_meal',
    userId,
    window,
    `${best.label} showed up on ${best.days} days`,
    `This is the food you logged on the most separate days in this period. You can save it as a quick meal so logging it again takes one tap.`,
    best.entryIds,
    `Counted how many different days each food name appeared on across your saved meals, then took the highest.`,
  );
}

function buildMacroBalance(
  entries: readonly FoodEntry[],
  userId: string,
  window: InsightWindow,
  daysLogged: number,
): FoodInsight | null {
  const totals = sumNutrients(entries.flatMap((e) => e.items.map((i) => i.nutrients))).nutrients;

  const proteinKcal = totals.proteinG * KCAL_PER_GRAM.protein;
  const carbsKcal = totals.carbsG * KCAL_PER_GRAM.carbs;
  const fatKcal = totals.fatG * KCAL_PER_GRAM.fat;
  const macroKcal = proteinKcal + carbsKcal + fatKcal;

  if (macroKcal <= 0) return null;

  const pct = (value: number) => Math.round((value / macroKcal) * 100);
  const proteinPerDay = Math.round(totals.proteinG / daysLogged);

  return makeInsight(
    'macro_balance',
    userId,
    window,
    `${pct(proteinKcal)}% protein, ${pct(carbsKcal)}% carbs, ${pct(fatKcal)}% fat`,
    `Across everything you logged, that is roughly ${proteinPerDay} g of protein per logged day. This describes what you recorded; it is not a recommendation.`,
    entries.map((e) => e.id),
    `Converted the protein, carb and fat grams of every saved item to calories at 4, 4 and 9 kcal per gram, then took each macro's share of that total.`,
  );
}

function buildVariety(
  entries: readonly FoodEntry[],
  userId: string,
  window: InsightWindow,
): FoodInsight | null {
  const distinct = new Set<string>();
  for (const entry of entries) {
    for (const item of entry.items) {
      const label = item.name.trim().toLowerCase();
      if (label.length > 0) distinct.add(label);
    }
  }

  if (distinct.size === 0) return null;

  return makeInsight(
    'variety',
    userId,
    window,
    `${distinct.size} different foods`,
    `You logged ${distinct.size} distinct food names in this period. Foods typed slightly differently count separately, so this is a rough measure.`,
    entries.map((e) => e.id),
    `Counted unique food names across your saved meals, ignoring capitalisation.`,
  );
}

function buildLoggingStreak(
  entries: readonly FoodEntry[],
  userId: string,
  window: InsightWindow,
): FoodInsight | null {
  const logged = new Set(entries.map((e) => toDateKey(new Date(e.consumedAt))));
  const keys = dateKeysInRange(window.periodStart, window.periodEnd);

  // Longest run of consecutive logged days inside the window.
  let longest = 0;
  let current = 0;
  for (const key of keys) {
    if (logged.has(key)) {
      current += 1;
      longest = Math.max(longest, current);
    } else {
      current = 0;
    }
  }

  if (longest < 2) return null;

  return makeInsight(
    'logging_streak',
    userId,
    window,
    `${longest} days in a row`,
    `Your longest run of consecutive days with at least one meal logged in this period.`,
    entries.map((e) => e.id),
    `Walked each day in the period and measured the longest unbroken run that had a saved meal.`,
  );
}
